CREATE VIEW vw_game_preference_similarity AS SELECT GameKey, GameID, GameTitle, round(avg(CASE  WHEN ((PreferenceTier = 'S')) THEN (similarity_pct) ELSE NULL END), 2) AS avg_s_similarity, round(max(CASE  WHEN ((PreferenceTier = 'S')) THEN (similarity_pct) ELSE NULL END), 2) AS max_s_similarity, round(avg(CASE  WHEN (((PreferenceTier = 'A') AND (ConditionalFlag = CAST('f' AS BOOLEAN)))) THEN (similarity_pct) ELSE NULL END), 2) AS avg_a_similarity, round(max(CASE  WHEN (((PreferenceTier = 'A') AND (ConditionalFlag = CAST('f' AS BOOLEAN)))) THEN (similarity_pct) ELSE NULL END), 2) AS max_a_similarity, round(avg(CASE  WHEN ((PreferenceTier IN ('B', 'C'))) THEN (similarity_pct) ELSE NULL END), 2) AS avg_lower_similarity, round(max(CASE  WHEN ((PreferenceTier IN ('B', 'C'))) THEN (similarity_pct) ELSE NULL END), 2) AS max_lower_similarity FROM vw_game_seed_similarity GROUP BY GameKey, GameID, GameTitle;
